(()=>{var t=document.getElementById("pageview");if(t){let a=["home","nota","Deportes"],e=JSON.parse(t.textContent)||{};if(a.includes(e.pagetype)){let s=localStorage.getItem("SchemaPageViewMetaRefresh")!=null?"yes":"no";e.metarefresh=s,t.textContent=JSON.stringify(e,null,2),localStorage.removeItem("SchemaPageViewMetaRefresh")}}})();
